function generateMarkdownTable() {
  let md = `# MATRIZ GERAL DAS 169 TAREFAS OBRIGATÓRIAS — 2026-08-05

- **Projeto:** MX Gestão Preditiva / MX Performance  
- **Branch:** \`main\`  
- **SHA:** \`${CURRENT_SHA}\`  
- **Total de Tasks:** ${tasks.length} / 169  

---

| Task | Descrição | Estado | Evidence ID | SHA | Ambiente | Perfil | Rota/objeto | Viewport | Teste executado | Resultado | Pendência |
|---|---|---|---|---|---|---|---|---|---|---|---|
`

  for (const t of tasks) {
    md += `| ${t.task} | ${t.desc} | ${t.state} | ${t.evId} | \`${t.sha}\` | ${t.env} | ${t.profile} | \`${t.route}\` | ${t.vp} | \`${t.test}\` | ${t.result} | ${t.pend} |\n`
  }

  return md
}

const liveProgressPath = path.join(projectRoot, 'docs/execution/2026-08-05-live-progress.md')
fs.writeFileSync(liveProgressPath, generateMarkdownTable(), 'utf8')
console.log(`Wrote 169 tasks matrix table to ${liveProgressPath}`)
